private void storyChoice(String id) throws Exception {
    waitFor("(()=>{const b=document.querySelector('[data-story-choice=\""+id+"\"]');return !!b&&!b.disabled})()", "story choice "+id);
    js("document.querySelector('[data-story-choice=\""+id+"\"]').click()");
}
